        baslik[m.group(2)] = m.group(3)
# üst bölüm başlık biçimi
print("ilk 3 üst başlık örneği:")
for s in satirlar:
    if re.match(r"^#\s", s) and not s.startswith("##"):
        print("   ", s[:90])
        break
ek_basla = next(i for i, s in enumerate(satirlar) if s.startswith("# Ekler"))
ek_metin = satirlar[ek_basla:]

def sutun_say(satir_kumesi, ilk_baslik_icerigi, sutun_idx):
    """Tablodaki belirli sütunun hücrelerinden sayıları çıkar."""
    cikti = []
    ic = False
    for s in satir_kumesi:
        if s.startswith("|") and ilk_baslik_icerigi in s:
            ic = True
            continue
        if ic:
            if not s.startswith("|"):
                break
            if set(s.replace("|", "").strip()) <= set("-"):
                continue
            hucre = [h.strip() for h in s.strip().strip("|").split("|")]
            if len(hucre) > sutun_idx:
                cikti.append((hucre[0], hucre[sutun_idx]))
    return cikti

# Ek F: son sütun Bölüm
ekf = sutun_say(ek_metin, "| İleti (kısaltılmış)", 3)
print("\nEk F bölüm başvuruları:", len(ekf))
for ileti, b in ekf:
    for no in re.findall(r"\d+(?:\.\d+)*", b):
        durum = "OK " if no in baslik else "YOK"
        print(f"  {durum} {no:7} <- {ileti[:60]}")

# Ek E: ikinci sütun "Bölüm X.Y"
ekE = []
for s in ek_metin:
    m = re.match(r"^\|\s*(.+?)\s*\|\s*(Bölüm [^|]+?)\s*\|$", s)
    if m:
        ekE.append((m.group(1), m.group(2)))
print("\nEk E başvuruları:", len(ekE))
for konu, b in ekE:
    for no in re.findall(r"\d+(?:\.\d+)*", b):
        print(f"  {'OK ' if no in baslik else 'YOK'} {no:7} <- {konu[:60]}")

# Ek B ek tablo: Bölüm sütunu
ekb = sutun_say(ek_metin, "| Yazım | Bölüm | Ne yapar? |", 1)
print("\nEk B ek tablo:", len(ekb))
for yazim, b in ekb:
    for no in re.findall(r"\d+(?:\.\d+)*", b):
        print(f"  {'OK ' if no in baslik else 'YOK'} {no:7} <- {yazim[:50]}")

# Ek I tablosu: "Kılavuzda" sütunu
ekI = sutun_say(ek_metin, "| Belge | Ana konusu | Kılavuzda |", 2)
print("\nEk I tasarım tablosu:", len(ekI))
for belge, b in ekI:
    for no in re.findall(r"\d+(?:\.\d+)*", b):
        print(f"  {'OK ' if no in baslik else 'YOK'} {no:7} <- {belge[:70]}")

