import os, sys
sys.stdout.reconfigure(encoding="utf-8")
KOK = r"C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\uxb"
PARCALAR = [
    "unknown symbol", "assignment requires explicit cast", "conflicts with CLASS", "DELETE target must be DIM variable",
    "cannot be called from outside its class", "META_UNKNOWN_DIRECTIVE", "META_NEEDS_PP_B", "henuz uygulanmadi: S-146 adim",
    "SELF_DEADLOCK", "LOCK_DEADLOCK", "TASK_WAIT_CYCLE", "field assignment denied", "array not declared", "coverage failed",
    "must not be absolute path", "host binding missing", "NATIVE_ONLY_UNSUPPORTED_ON_JS", "UXB_RUNTIME_HOST_UNBOUND",
    "WAT string linear-memory lowering is not implemented", "does not support floating-point values", "[canonical=",
    "invalid collection handle", "call stack limit exceeded", "stack overflow", "step limit exceeded", "--max-steps",
]
KLASORLER = ["src", "native", "compiler", "include", "libsx"]
UZANTI = (".fbs", ".bi", ".bas", ".cpp", ".h", ".hpp", ".js", ".py", ".ps1", ".uxb", ".uxmh", ".txt", ".json")
bulunan = {p: [] for p in PARCALAR}
for k in KLASORLER:
    for kok, dizinler, dosyalar in os.walk(os.path.join(KOK, k)):
        dizinler[:] = [d for d in dizinler if d.lower() not in ("build", "node_modules", ".git", "__pycache__")]
        for f in dosyalar:
            if not f.lower().endswith(UZANTI):
                continue
            yol = os.path.join(kok, f)
            try:
                if os.path.getsize(yol) > 4_000_000:
                    continue
                t = open(yol, encoding="utf-8", errors="replace").read()
            except OSError:
                continue
            for p in PARCALAR:
                if p in t and len(bulunan[p]) < 3:
                    satir = next((i for i, s in enumerate(t.split("\n"), 1) if p in s), 0)
                    bulunan[p].append(f"{os.path.relpath(yol, KOK)}:{satir}")
for p in PARCALAR:
    print(("OK   " if bulunan[p] else "YOK  ") + p.ljust(55), bulunan[p][:2])

