# -*- coding: utf-8 -*-
"""Anlatım tablolarındaki iddiaları dört motorda sınar.
Kullanım: python iddia_denetle.py iddialar.json [--motor=AST,MIR,x64,JS] [--is=6]
iddialar.json: [{"ad": "...", "once": "DIM satırları (isteğe bağlı)", "ifade": "LEN(\"a\")", "beklenen": "1"}, ...]
  "ifade" PRINT edilir; "kod" verilirse program olduğu gibi çalıştırılır. "beklenen": tek satır (ya da liste: satırlar),
  "HATA" yazılırsa herhangi bir hata/ret beklenir. "yoksay": ["JS"] verilen motorlar karşılaştırılmaz."""
import os, sys, json, tempfile, shutil, subprocess, concurrent.futures as cf
sys.stdout.reconfigure(encoding="utf-8")
KOK = r"C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\uxb"
EXE = os.path.join(KOK, "bin", "uxb_kilavuz_20261007.exe")
DLL = os.path.join(KOK, "bin", "uxb_runtime.dll")


def calis(k, cwd, sure=240):
    try:
        r = subprocess.run(k, cwd=cwd, capture_output=True, timeout=sure)
        c = (r.stdout + r.stderr).decode("utf-8", "replace").splitlines()
        return r.returncode, [s.rstrip() for s in c if s.strip() and not s.startswith(("INFO", "WARN"))]
    except subprocess.TimeoutExpired:
        return -9, ["ZAMAN_ASIMI"]


def motor_calistir(motor, yol, d):
    if motor == "AST":
        return calis([EXE, "run", yol, "--out-root", d], KOK)
    if motor == "MIR":
        return calis([EXE, "run", yol, "--interpreter-backend", "MIR", "--out-root", d], KOK)
    if motor == "x64":
        exe = os.path.join(d, "p.exe")
        rc, c = calis([EXE, "bld", yol, "--build-x64", "--build-x64-out", exe, "--out-root", d], KOK)
        if not os.path.exists(exe):
            return "DERLENMEDI", c[-1:]
        shutil.copy(DLL, d)
        return calis([exe], d)
    if motor == "JS":
        js = os.path.join(d, "p.js")
        rc, c = calis([EXE, "jsw", yol, "--js-out", js, "--out-root", d], KOK)
        if not os.path.exists(js):
            return "DERLENMEDI", c[-1:]
        return calis(["node", js], d)


def bir(i, ogd, motorlar):
    d = tempfile.mkdtemp(prefix="id_")
    yol = os.path.join(d, f"p{i}.uxb")
    kod = ogd.get("kod") or ((ogd.get("once", "") + "\n" if ogd.get("once") else "") + "PRINT " + ogd["ifade"])
    open(yol, "w", encoding="utf-8", newline="\r\n").write(kod + "\n")
    sonuc = {}
    try:
        for m in motorlar:
            if m in ogd.get("yoksay", []):
                continue
            sonuc[m] = motor_calistir(m, yol, d)
    finally:
        shutil.rmtree(d, ignore_errors=True)
    return i, ogd, sonuc


def main():
    iddialar = json.load(open(sys.argv[1], encoding="utf-8"))
    motorlar, isci = ["AST", "MIR", "x64", "JS"], 6
    for a in sys.argv[2:]:
        if a.startswith("--motor="):
            motorlar = a[8:].split(",")
        elif a.startswith("--is="):
            isci = int(a[5:])
    hatali = 0
    with cf.ThreadPoolExecutor(isci) as ex:
        isler = list(ex.map(lambda t: bir(t[0], t[1], motorlar), enumerate(iddialar)))
    for i, ogd, sonuc in isler:
        bek = ogd["beklenen"]
        bek = bek if isinstance(bek, list) else [bek]
        farklar = []
        for m, (rc, cikti) in sonuc.items():
            if bek == ["HATA"]:
                ok = (rc not in (0,)) or any("ERROR" in s or "error" in s for s in cikti)
            else:
                ok = rc == 0 and cikti == bek
            if not ok:
                farklar.append(f"{m}: rc={rc} {cikti[:3]}")
        if farklar:
            hatali += 1
            print(f"[{i:03d}] {ogd.get('ad') or ogd.get('ifade') or ''}  beklenen={bek}")
            for f in farklar:
                print("        ", f[:200])
    print(f"toplam {len(iddialar)} iddia, farklı olan {hatali}")


main()

# -*- coding: utf-8 -*-
"""Bir metin dosyasındaki ('=====' ile ayrılmış, ilk satır başlık) küçük programları dört motorda çalıştırır.
Kullanım: python coklu_dene.py dosya.txt [--is=3] [--n=8] [--motor=AST,MIR,x64,JS] [--sadece=baslikta_gecen]
Her parça geçici klasörde derlenir ve çalıştırılır; çıktı satırları kısaltılarak yan yana yazılır."""
import os, sys, subprocess, tempfile, shutil, concurrent.futures as cf

sys.stdout.reconfigure(encoding="utf-8")
KOK = r"C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\uxb"
EXE = os.path.join(KOK, "bin", "uxb_kilavuz_20261007.exe")
DLL = os.path.join(KOK, "bin", "uxb_runtime.dll")


def calis(k, cwd, sure=240):
    try:
        r = subprocess.run(k, cwd=cwd, capture_output=True, timeout=sure)
        c = (r.stdout + r.stderr).decode("utf-8", "replace").splitlines()
        return r.returncode, [s.rstrip() for s in c if s.strip() and not s.startswith(("INFO", "WARN"))]
    except subprocess.TimeoutExpired:
        return -9, ["ZAMAN_ASIMI"]


def parca_calistir(sira, baslik, kod, motorlar, n):
    d = tempfile.mkdtemp(prefix="cd_")
    yol = os.path.join(d, f"p{sira}.uxb")
    open(yol, "w", encoding="utf-8", newline="\r\n").write(kod + "\n")
    sonuc = {}
    try:
        if "AST" in motorlar:
            rc, c = calis([EXE, "run", yol, "--out-root", d], KOK)
            sonuc["AST"] = (rc, c[:n])
        if "MIR" in motorlar:
            rc, c = calis([EXE, "run", yol, "--interpreter-backend", "MIR", "--out-root", d], KOK)
            sonuc["MIR"] = (rc, c[:n])
        if "x64" in motorlar:
            exe = os.path.join(d, "p.exe")
            rc, c = calis([EXE, "bld", yol, "--build-x64", "--build-x64-out", exe, "--out-root", d], KOK)
            if os.path.exists(exe):
                shutil.copy(DLL, d)
                rc2, c2 = calis([exe], d)
                sonuc["x64"] = (rc2, c2[:n])
            else:
                sonuc["x64"] = ("DERLENMEDI", c[-2:])
        if "JS" in motorlar:
            js = os.path.join(d, "p.js")
            rc, c = calis([EXE, "jsw", yol, "--js-out", js, "--out-root", d], KOK)
            if os.path.exists(js):
                rc2, c2 = calis(["node", js], d)
                sonuc["JS"] = (rc2, c2[:n])
            else:
                sonuc["JS"] = ("DERLENMEDI", c[-2:])
    finally:
        shutil.rmtree(d, ignore_errors=True)
    return sira, baslik, sonuc


def main():
    yol = sys.argv[1]
    isci, n, motorlar, sadece = 3, 8, ["AST", "MIR", "x64", "JS"], None
    for a in sys.argv[2:]:
        if a.startswith("--is="):
            isci = int(a[5:])
        elif a.startswith("--n="):
            n = int(a[4:])
        elif a.startswith("--motor="):
            motorlar = a[8:].split(",")
        elif a.startswith("--sadece="):
            sadece = a[9:]
    metin = open(yol, encoding="utf-8").read().replace("\r\n", "\n")
    parcalar = []
    for i, p in enumerate(metin.split("=====")):
        satirlar = p.strip("\n").split("\n")
        if not satirlar or not satirlar[0].strip():
            continue
        baslik, kod = satirlar[0].strip(), "\n".join(satirlar[1:])
        if sadece and sadece not in baslik:
            continue
        parcalar.append((i + 1, baslik, kod))
    with cf.ThreadPoolExecutor(max_workers=isci) as ex:
        isler = [ex.submit(parca_calistir, s, b, k, motorlar, n) for s, b, k in parcalar]
        sonuclar = sorted((f.result() for f in cf.as_completed(isler)), key=lambda t: t[0])
    for sira, baslik, sonuc in sonuclar:
        print(f"## {baslik}")
        for m in motorlar:
            rc, c = sonuc.get(m, ("-", []))
            print(f"   {m:<4}: {rc} {c}")
        sys.stdout.flush()


main()

