        print("  ", o)
print("\n##### JSON olup schema VE status alanı OLMAYANLAR (dict ise)")
yok = []
for o, vr in A.items():
    for f in SIRA:
        r = vr.get(f)
        if r and durum(r) == "OK" and r.get("tur") == "json" and r.get("schema") is not None:
