for etiket, kos in [("schema var, status yok", lambda r: r["schema"] and not r["status"]), ("status var, schema yok", lambda r: r["status"] and not r["schema"]), ("ikisi de var", lambda r: r["schema"] and r["status"])]:
    liste = []
    for o, vr in A.items():
        for f in SIRA:
            r = vr.get(f)
            if r and durum(r) == "OK" and r.get("tur") == "json" and r.get("schema") is not None:
                if kos(r):
                    liste.append(o)
                break
    print(f"  {etiket} ({len(liste)}):", ", ".join(liste))
print("\n##### bld fiilinde dosya yazanlar vs yazmayanlar")
