# -*- coding: utf-8 -*-
"""SORUN_TAKIP.md: S-205 ve sonrası kayıtların Durum alanı dağılımı; ACIK olmayanları ve son Güncelleme(Codex) satırlarını listeler."""
import collections, re, sys
sys.stdout.reconfigure(encoding="utf-8")
YOL = r"C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\uxb\ai_koordinasyon\SORUN_TAKIP.md"
satirlar = open(YOL, encoding="utf-8").read().split("\n")
kayit = []
for i, s in enumerate(satirlar):
    m = re.match(r"^## S-(\d+)\b(.*)", s)
    if m:
        kayit.append([int(m.group(1)), i, m.group(2).strip()])
for k, n in zip(kayit, kayit[1:] + [[0, len(satirlar), ""]]):
    k.append(n[1])
dag = collections.Counter()
degisen = []
for no, bas, baslik, bit in kayit:
    if no < 205:
        continue
    blok = satirlar[bas:bit]
    durum = None
    for s in blok:
        m = re.search(r"\*\*Durum:\*\*\s*`([^`]+)`", s)
        if m:
            durum = m.group(1)
            break
    dag[durum] += 1
    if durum != "ACIK":
        degisen.append((no, durum, baslik[:110]))
print("S>=205 durum dağılımı:", dict(dag))
print("\n== ACIK olmayanlar ==")
for no, d, b in degisen:
    print(f"  S-{no}  {d:<34} {b}")
print("\n== son 'Güncelleme (Codex' / 'Codex' satırları (ilk 160 karakter) ==")
n = 0
for no, bas, baslik, bit in kayit:
    if no < 205:
        continue
    for s in satirlar[bas:bit]:
        if re.search(r"Codex", s) and ("Güncelleme" in s or "Düzeltme" in s or "Kapan" in s):
            print(f"  S-{no}: {s.strip()[:170]}")
            n += 1
            break
print("toplam:", n)

